// Reading passages: 25 per level (1 = A1-A2, 2 = B1-B2, 3 = C1-C2), each with 3 multiple-choice questions.
// answer = index (0-3) of the correct option.
const READING = [
  {id: 1, level: 1, title: "My Morning Routine",
   text: "I wake up at six o'clock every morning. First, I drink a glass of water. Then I take a quick shower and eat breakfast. I usually have toast with cheese and a cup of coffee. At seven thirty, I walk to the bus stop. The bus takes twenty minutes to reach my office. I like my morning routine because it helps me start the day calmly.",
   questions: [{q: "What time does the narrator wake up?", options: ["Five o'clock", "Six o'clock", "Seven thirty", "Eight o'clock"], answer: 1}, {q: "What does the narrator usually eat for breakfast?", options: ["Rice and fish", "Eggs and bread", "Toast with cheese", "Soup and salad"], answer: 2}, {q: "How does the narrator get to the office?", options: ["By car", "By bike", "On foot only", "By bus"], answer: 3}]},
  {id: 2, level: 1, title: "My Family",
   text: "I have a big family. My father is a teacher, and my mother works in a hospital. I have two brothers and one sister. My older brother lives in London. My younger sister is still a student. We often meet on Saturdays for lunch at my grandmother's house. She cooks the best soup in town. Everyone in my family loves to laugh and talk.",
   questions: [{q: "What is the narrator's father's job?", options: ["Doctor", "Teacher", "Driver", "Nurse"], answer: 1}, {q: "Where does the older brother live?", options: ["In Haifa", "In London", "At home", "In Paris"], answer: 1}, {q: "Where does the family often have lunch?", options: ["At a restaurant", "At school", "At grandmother's house", "At the office"], answer: 2}]},
  {id: 3, level: 1, title: "A Visit to the Market",
   text: "On Friday, I went to the market with my friend Nora. The market is very busy and full of colors. We bought fresh tomatoes, cucumbers, and some green peppers. The fruit seller gave us a free orange because we were kind customers. Nora bought some flowers for her mother. We spent about two hours there. Then we went home and cooked a big salad together.",
   questions: [{q: "When did the narrator go to the market?", options: ["On Monday", "On Friday", "On Sunday", "On Saturday"], answer: 1}, {q: "What did they buy?", options: ["Bread and milk", "Fish and rice", "Vegetables", "Chocolate and cake"], answer: 2}, {q: "Why did the seller give them an orange?", options: ["It was cheap", "They were kind customers", "It was old", "It was their birthday"], answer: 1}]},
  {id: 4, level: 1, title: "The Weather Today",
   text: "Today the weather is cold and rainy. The sky is gray, and the wind is strong. In the morning it was sunny, but now it is raining. I took my umbrella to work. Tomorrow the weather will be better, the news says. The temperature will be around twenty degrees, and the sun will come out in the afternoon. I hope we can go to the park then.",
   questions: [{q: "How is the weather today?", options: ["Hot and sunny", "Cold and rainy", "Warm and windy", "Snowy"], answer: 1}, {q: "What did the narrator take to work?", options: ["A hat", "A coat", "An umbrella", "A book"], answer: 2}, {q: "What does the news say about tomorrow?", options: ["It will snow", "It will be better", "It will be cold", "It will rain all day"], answer: 1}]},
  {id: 5, level: 1, title: "My Favorite Food",
   text: "My favorite food is pasta. I eat it at least twice a week. My mother makes the best pasta with tomato sauce and fresh basil. Sometimes I add cheese on top. My brother likes pasta too, but he prefers it with butter and garlic. When we have guests, my mother cooks a big pot of pasta. Everyone asks for the recipe, but she never tells them her secret.",
   questions: [{q: "How often does the narrator eat pasta?", options: ["Once a month", "At least twice a week", "Every day", "Never"], answer: 1}, {q: "How does the brother like his pasta?", options: ["With tomato sauce", "With butter and garlic", "With fish", "With cream"], answer: 1}, {q: "What does the mother never tell people?", options: ["Her price", "Her secret recipe", "Her age", "Her job"], answer: 1}]},
  {id: 6, level: 1, title: "A Day at the Office",
   text: "I work at a small office in the city center. Our team has five people. Every morning we have a short meeting to plan the day. I answer emails, call clients, and write reports. At lunch time, I usually eat a sandwich at my desk. In the afternoon, my manager asks me to help with a new project. I leave the office at five o'clock, and I am usually tired but happy.",
   questions: [{q: "Where is the office?", options: ["In the suburbs", "In the city center", "Near the beach", "In a shopping mall"], answer: 1}, {q: "How many people are in the team?", options: ["Three", "Four", "Five", "Six"], answer: 2}, {q: "What does the narrator do at lunch?", options: ["Goes to a restaurant", "Eats a sandwich at the desk", "Goes home", "Plays soccer"], answer: 1}]},
  {id: 7, level: 1, title: "A Trip to the Beach",
   text: "Last summer, we went to the beach for a week. The water was warm and the sand was soft. Every day, my children built sandcastles and swam in the sea. I read books under a big umbrella. In the evening, we ate fish at a small restaurant near the port. The trip was short but very relaxing. We want to go back next year.",
   questions: [{q: "How long was the trip?", options: ["One day", "One weekend", "One week", "One month"], answer: 2}, {q: "What did the children do every day?", options: ["Read books", "Built sandcastles and swam", "Went to school", "Slept all day"], answer: 1}, {q: "Where did they eat fish?", options: ["At home", "At a small restaurant near the port", "On the boat", "At a hotel buffet"], answer: 1}]},
  {id: 8, level: 1, title: "Learning English",
   text: "I study English three times a week at a language school. My teacher is very kind, and she speaks slowly when we practice. In class, we talk about our jobs and our hobbies. I like the reading lessons most, because I can learn new words. I write new words in a small notebook and I read them before I sleep. My goal is to speak English well for my next trip to London.",
   questions: [{q: "How often does the narrator study English?", options: ["Once a week", "Twice a week", "Three times a week", "Every day"], answer: 2}, {q: "What does the narrator like most?", options: ["Writing lessons", "Reading lessons", "Speaking tests", "Listening games"], answer: 1}, {q: "Why does the narrator want to speak English well?", options: ["For a job interview", "For a trip to London", "For school", "For a movie"], answer: 1}]},
  {id: 9, level: 1, title: "My Neighborhood",
   text: "I live in a quiet neighborhood near the park. There are many trees and a small playground for children. In the morning, I hear birds singing. There is a bakery on the corner, and the bread smells wonderful. The supermarket is five minutes away on foot. My neighbors are friendly. Last week, an old man helped me carry my heavy bag up the stairs.",
   questions: [{q: "Where does the narrator live?", options: ["In a big city", "In a quiet neighborhood", "On a farm", "Near the airport"], answer: 1}, {q: "What is on the corner?", options: ["A bank", "A bakery", "A school", "A bus station"], answer: 1}, {q: "What did an old man do last week?", options: ["He gave the narrator money", "He helped carry a heavy bag", "He sold bread", "He called the police"], answer: 1}]},
  {id: 10, level: 1, title: "Shopping for Clothes",
   text: "Yesterday I went shopping for new shoes. The shop was very crowded, so I waited for twenty minutes. I tried on three pairs. The first ones were too small, and the second ones were too big. The third pair fit perfectly. They were a little expensive, but they are very comfortable. I wore them to the party last night, and everyone liked them.",
   questions: [{q: "What did the narrator buy?", options: ["A jacket", "New shoes", "A hat", "Trousers"], answer: 1}, {q: "How long did the narrator wait?", options: ["Ten minutes", "Twenty minutes", "An hour", "Five minutes"], answer: 1}, {q: "What was wrong with the first pair?", options: ["They were too small", "They were too big", "They were dirty", "They were too cheap"], answer: 0}]},
  {id: 11, level: 1, title: "My Pet Dog",
   text: "We have a small brown dog named Max. He is three years old and very friendly. Every morning, Max waits by the door for his walk. He likes to run in the grass and play with the ball. At night, he sleeps on a blanket next to my bed. My children love him very much. Sometimes he eats too much, so we have to watch what he eats.",
   questions: [{q: "What is the dog's name?", options: ["Charlie", "Max", "Bella", "Rex"], answer: 1}, {q: "How old is Max?", options: ["One year old", "Two years old", "Three years old", "Five years old"], answer: 2}, {q: "Where does Max sleep?", options: ["In the garden", "On a blanket next to the bed", "In the car", "In the kitchen"], answer: 1}]},
  {id: 12, level: 1, title: "A Phone Call",
   text: "Yesterday my friend Dan called me from the airport. He was going to visit his parents in Canada. He was very excited about the trip. We talked for almost ten minutes. He told me about his new job and his plans for the summer. Before we hung up, he promised to send me photos from the trip. I am waiting for them now.",
   questions: [{q: "Where was Dan when he called?", options: ["At home", "At the airport", "At work", "At a restaurant"], answer: 1}, {q: "Where is Dan going?", options: ["To Canada", "To Italy", "To Spain", "To London"], answer: 0}, {q: "What did Dan promise to do?", options: ["Call again tomorrow", "Send photos", "Visit the narrator", "Pay the bill"], answer: 1}]},
  {id: 13, level: 1, title: "Cooking Dinner",
   text: "Tonight I want to cook a simple dinner. I will make chicken with rice and some vegetables. First, I cut the onion and the carrots. Then I put the chicken in a hot pan with a little oil. After ten minutes, I add the vegetables and salt. The rice takes about twenty minutes to cook. Dinner is ready at eight o'clock, and my family is hungry.",
   questions: [{q: "What will the narrator cook?", options: ["Fish and potatoes", "Chicken with rice", "Pasta and salad", "Soup"], answer: 1}, {q: "What is added after the chicken?", options: ["Milk", "Vegetables and salt", "Cheese", "Sugar"], answer: 1}, {q: "What time is dinner ready?", options: ["Seven o'clock", "Eight o'clock", "Nine o'clock", "Six o'clock"], answer: 1}]},
  {id: 14, level: 1, title: "A Rainy Weekend",
   text: "It rained all weekend, so we stayed at home. On Saturday, I read a long book and my daughter drew pictures. In the afternoon, we played board games and laughed a lot. On Sunday, we baked a chocolate cake. It was warm and sweet. When the rain stopped in the evening, we walked outside and looked at the wet trees. It was a good weekend.",
   questions: [{q: "What did the family do on Saturday?", options: ["They went to the beach", "They stayed at home", "They visited friends", "They went to the mall"], answer: 1}, {q: "What did they bake?", options: ["Bread", "A chocolate cake", "Cookies", "A pizza"], answer: 1}, {q: "When did the rain stop?", options: ["In the morning", "In the afternoon", "In the evening", "At night"], answer: 2}]},
  {id: 15, level: 1, title: "Going to the Doctor",
   text: "Last week I felt sick, so I went to see the doctor. The waiting room was full of people. After half an hour, the nurse called my name. The doctor asked me some questions and checked my throat. He said I had a cold. He gave me some medicine and told me to drink a lot of water and rest. I feel much better now.",
   questions: [{q: "Why did the narrator go to the doctor?", options: ["To get a new job", "Because they felt sick", "To buy medicine", "To visit a friend"], answer: 1}, {q: "How long did the narrator wait?", options: ["Ten minutes", "Half an hour", "Two hours", "Five minutes"], answer: 1}, {q: "What did the doctor say the narrator had?", options: ["A cold", "A broken arm", "Flu", "A headache"], answer: 0}]},
  {id: 16, level: 1, title: "My Hobby: Painting",
   text: "I started painting two years ago. At first, my pictures were not very good, but I practiced every weekend. Now I paint landscapes and flowers in bright colors. My favorite color is blue. I paint in my small room near the window, where the light is good. Last month, one of my pictures was shown at a small art show in the library. People said they liked it.",
   questions: [{q: "When did the narrator start painting?", options: ["Ten years ago", "Two years ago", "Last month", "Five years ago"], answer: 1}, {q: "What is the narrator's favorite color?", options: ["Red", "Green", "Yellow", "Blue"], answer: 3}, {q: "Where was a picture shown?", options: ["In a museum", "At an art show in the library", "In a school", "On the internet"], answer: 1}]},
  {id: 17, level: 1, title: "A Job Interview",
   text: "Tomorrow I have a job interview at a hotel. I am a little nervous, but I am also excited. I have prepared my answers and I have checked my clothes. I will arrive ten minutes early, because my teacher says it is important. I will bring my ID and my papers. I hope the manager will like me and I will get the job.",
   questions: [{q: "Where is the job interview?", options: ["At a school", "At a hotel", "At a bank", "At a shop"], answer: 1}, {q: "Why will the narrator arrive early?", options: ["Because the teacher said it is important", "Because the bus is fast", "Because the manager asked", "Because it is cold"], answer: 0}, {q: "What will the narrator bring?", options: ["Food and water", "An ID and papers", "A book", "A computer"], answer: 1}]},
  {id: 18, level: 1, title: "The Park",
   text: "On Sunday afternoon, I like to go to the park near my house. There is a big lake with ducks and a path for walking. Children ride their bicycles, and old people sit on benches and read newspapers. I usually walk for an hour and then sit under a tree to rest. Sometimes I bring a sandwich and eat it by the lake. The park makes me feel calm.",
   questions: [{q: "When does the narrator go to the park?", options: ["On Monday morning", "On Sunday afternoon", "On Friday night", "On Saturday evening"], answer: 1}, {q: "What is in the park?", options: ["A big lake with ducks", "A swimming pool", "A soccer field", "A zoo"], answer: 0}, {q: "How does the park make the narrator feel?", options: ["Angry", "Tired", "Calm", "Afraid"], answer: 2}]},
  {id: 19, level: 1, title: "Public Transport",
   text: "I take the train to work every day. The train station is ten minutes from my house by bus. The train is usually on time, but on Tuesday it was late because of a problem with the signal. I bought a monthly ticket, which is cheaper than paying every day. On the train, I often read the news or listen to music. It takes forty minutes to reach the city.",
   questions: [{q: "How does the narrator usually travel to work?", options: ["By car", "By train", "By bike", "On foot"], answer: 1}, {q: "Why was the train late on Tuesday?", options: ["Because of snow", "Because of a problem with the signal", "Because the driver was sick", "Because of a strike"], answer: 1}, {q: "How long does the train ride take?", options: ["Ten minutes", "Twenty minutes", "Forty minutes", "One hour"], answer: 2}]},
  {id: 20, level: 1, title: "Learning to Cook",
   text: "When I was young, I could not cook at all. My mother always made dinner. But last year I decided to learn. I watched videos and bought a simple cookbook. My first meal was an omelette, and it was a little burnt. Now I cook almost every evening. My favorite dish is vegetable soup. My friends say my soup is very good, and I am proud of it.",
   questions: [{q: "What was the narrator's first meal?", options: ["Soup", "An omelette", "A cake", "Pasta"], answer: 1}, {q: "How did the narrator learn to cook?", options: ["By taking classes", "By watching videos and using a cookbook", "From a friend", "From the mother"], answer: 1}, {q: "What is the narrator's favorite dish?", options: ["Chicken", "Pizza", "Vegetable soup", "Salad"], answer: 2}]},
  {id: 21, level: 1, title: "A Birthday Party",
   text: "Last Saturday was my sister's birthday. We had a party at our house. My mother made a big chocolate cake with strawberries on top. My brother bought balloons and a funny hat. Many friends came and brought small gifts. We played music and danced in the living room. At the end of the night, everyone sang happy birthday, and my sister smiled and blew out the candles.",
   questions: [{q: "Whose birthday was it?", options: ["The mother's", "The brother's", "The sister's", "The narrator's"], answer: 2}, {q: "What was on top of the cake?", options: ["Chocolate", "Strawberries", "Cream", "Nuts"], answer: 1}, {q: "What did they do at the end of the night?", options: ["They went to sleep", "They sang happy birthday", "They cleaned the house", "They ate dinner"], answer: 1}]},
  {id: 22, level: 1, title: "My Room",
   text: "My room is small, but I like it very much. There is a bed, a desk, and a big window. On the desk I have a lamp, my laptop, and some books. The walls are painted light green. I keep my clothes in a wooden closet. Every evening I tidy my room before I go to sleep. A clean room helps me feel relaxed and ready for the next day.",
   questions: [{q: "What color are the walls?", options: ["White", "Light green", "Blue", "Yellow"], answer: 1}, {q: "What is on the desk?", options: ["A lamp, a laptop, and books", "A tv and a radio", "Plates and cups", "Shoes"], answer: 0}, {q: "Why does the narrator tidy the room?", options: ["Because guests are coming", "Because it helps them relax", "Because the mother asks", "Because they like dust"], answer: 1}]},
  {id: 23, level: 1, title: "At the Bank",
   text: "Yesterday I went to the bank to open a new account. The clerk was friendly and helped me fill in the forms. I needed my ID, my address, and a letter from my job. After twenty minutes, the account was ready. The clerk gave me a card and a small book. She said I can use the card in shops and at the cash machine. I was happy that everything was simple.",
   questions: [{q: "Why did the narrator go to the bank?", options: ["To take a loan", "To open a new account", "To pay a bill", "To change money"], answer: 1}, {q: "What did the narrator need to bring?", options: ["Only an ID", "An ID, an address, and a letter from work", "A photo and a pen", "Money and a card"], answer: 1}, {q: "What did the clerk give the narrator?", options: ["A map", "A phone", "A card and a small book", "A pen and paper"], answer: 2}]},
  {id: 24, level: 1, title: "Summer Vacation",
   text: "Every summer, my family goes to the mountains for two weeks. We rent a small wooden house near a river. In the morning, we go hiking, and in the afternoon, we swim in the cold water. My father likes to fish, and my mother reads books on the porch. In the evening, we make a fire and tell stories. It is always the best time of the year for us.",
   questions: [{q: "Where does the family go in the summer?", options: ["To the sea", "To the mountains", "To a big city", "To another country"], answer: 1}, {q: "How long is the vacation?", options: ["One week", "Two weeks", "One month", "Three days"], answer: 1}, {q: "What does the father like to do?", options: ["Swim", "Hike", "Fish", "Read books"], answer: 2}]},
  {id: 25, level: 1, title: "My Dream Job",
   text: "When I was a child, I wanted to be a pilot. I loved looking at planes in the sky. Now I work with computers, but I still think about flying. Last year I took a small course and learned about airplanes. My teacher says it is possible to become a pilot at any age. I am not sure yet, but I am saving money and I want to try. Maybe one day I will fly to London myself.",
   questions: [{q: "What did the narrator want to be as a child?", options: ["A doctor", "A pilot", "A teacher", "A driver"], answer: 1}, {q: "What does the narrator do now?", options: ["Works with computers", "Flies planes", "Teaches English", "Cooks in a restaurant"], answer: 0}, {q: "What is the narrator doing to make the dream possible?", options: ["Moving to London", "Saving money and trying", "Stopping the job", "Buying a plane"], answer: 1}]},
  {id: 26, level: 2, title: "The Remote Work Debate",
   text: "Many companies now let employees work from home for part of the week. Supporters argue that this saves time and money, since workers avoid long commutes. They also say that people can focus better in a quiet environment. Critics, however, worry that remote workers feel isolated and find it harder to build friendships with colleagues. Some managers also believe that spontaneous conversations in the office lead to better ideas. The best solution may be a hybrid model that combines both approaches. Advocates of a hybrid arrangement point out that it lets teams keep the flexibility of home work while still meeting in person for planning, training, and important decisions. Many employees report that a few office days each week help them feel connected to their colleagues and to the organization's culture. Companies that adopt this model often redesign their offices as collaborative spaces rather than rows of individual desks. The success of any arrangement, however, depends on clear expectations, fair treatment of employees who work remotely, and managers who measure output rather than the hours people spend at their desks. Ultimately, the right balance depends on the nature of each job, the needs of each team, and the preferences of each person involved in the work.",
   questions: [{q: "What is one advantage of remote work mentioned in the text?", options: ["Lower salaries", "Shorter commutes", "More meetings", "Fewer vacations"], answer: 1}, {q: "What do critics worry about?", options: ["Workers feel isolated", "Offices are too big", "Salaries are too high", "Internet is too slow"], answer: 0}, {q: "What does the author suggest as the best solution?", options: ["Ending remote work", "A hybrid model", "Working only at night", "Hiring more managers"], answer: 1}]},
  {id: 27, level: 2, title: "A Forgotten Invention",
   text: "Although most people have never heard of him, Hedy Lamarr helped lay the foundations for modern wireless communication. An actress in the 1930s, she was also a gifted inventor. During the Second World War, she developed a system that allowed radio signals to jump between frequencies, making them harder to jam. Her idea was patented, but the navy did not use it for many years. Today, similar technology is used in Wi-Fi and Bluetooth, so her work continues to influence our daily lives. Hedy Lamarr's story also illustrates how inventions can be ignored for reasons unrelated to their merit. Her frequency-hopping idea was filed in 1942 together with the composer George Antheil, who helped her translate the concept into a mechanism based on piano rolls. The patent was granted, yet the military did not adopt the system during the war. Only decades later did engineers recognize its value and incorporate it into communication devices. Her case is often cited by educators who want students to understand that scientific contributions can come from unexpected places and that recognition may arrive long after the work was done. Her story continues to inspire discussions about how unrecognised innovators can still shape the technologies that people use every single day.",
   questions: [{q: "What was Hedy Lamarr's profession in the 1930s?", options: ["Scientist", "Actress", "Engineer", "Teacher"], answer: 1}, {q: "Why was her radio system useful during the war?", options: ["It was cheap", "Signals were harder to jam", "It was very fast", "It needed no electricity"], answer: 1}, {q: "What modern technologies use similar ideas?", options: ["Television and radio", "Wi-Fi and Bluetooth", "Cars and trains", "Printers and scanners"], answer: 1}]},
  {id: 28, level: 2, title: "The Value of Sleep",
   text: "Sleep is often treated as a luxury, yet researchers increasingly regard it as essential for health. During sleep, the brain consolidates memories and removes waste products that accumulate during the day. Adults who sleep fewer than six hours a night show weaker concentration and a higher risk of heart problems. Interestingly, the quality of sleep matters as much as its length. Frequent interruptions, even brief ones, can reduce the benefits. Experts therefore recommend a consistent bedtime and a dark, cool room. Researchers studying sleep have also found that irregular schedules disturb the body's internal clock, a rhythm that governs hormones, body temperature, and alertness. Shift workers and frequent travelers often experience this disruption, which may contribute to fatigue and poor concentration. Simple habits can help: exposure to natural daylight in the morning, avoiding bright screens in the hour before bed, and keeping caffeine away from the afternoon. Some people also benefit from a short wind-down routine, such as reading a printed book or stretching gently, which signals to the brain that the day is ending and rest is approaching. A good night's sleep, in other words, is not a luxury that can be postponed, but a basic condition for thinking clearly and living well over time.",
   questions: [{q: "According to the text, what does the brain do during sleep?", options: ["It stops working completely", "It consolidates memories", "It learns new languages", "It produces heat"], answer: 1}, {q: "What do experts recommend?", options: ["A late bedtime and a warm room", "A consistent bedtime and a dark, cool room", "Sleeping in the afternoon only", "Drinking coffee before bed"], answer: 1}, {q: "What effect can frequent interruptions have?", options: ["They increase memory", "They reduce the benefits of sleep", "They make people taller", "They have no effect"], answer: 1}]},
  {id: 29, level: 2, title: "The Rise of Street Food",
   text: "Street food has moved from the margins of city life to the center of culinary culture. Once associated with low prices and hasty meals, it now attracts chefs who experiment with local ingredients and traditional recipes. Food markets in many cities have become tourist destinations, and some vendors have built successful restaurant chains. However, critics warn that rising rents and strict regulations make it difficult for small sellers to survive. Authorities must balance the desire for vibrant public spaces with the need to protect independent entrepreneurs. Street food vendors also play an important role in the economic life of many neighbourhoods. They provide affordable meals to workers, students, and families, and they often buy ingredients from local farmers and small suppliers. Some cities have responded by creating licensed street food zones with shared facilities such as water supply, waste collection, and electricity. Such schemes give vendors legal certainty while maintaining hygiene standards. Residents, meanwhile, appreciate the sense of energy that food stalls bring to the streets, especially in the evening, when markets become meeting places for friends and neighbors. For many visitors, eating at a stall is the most authentic way to understand a city, because it reveals the rhythms, tastes, and everyday routines of its residents.",
   questions: [{q: "How was street food traditionally viewed?", options: ["As expensive and formal", "As cheap and hasty", "As unhealthy and dangerous", "As a sign of wealth"], answer: 1}, {q: "What problem do critics identify?", options: ["Too few tourists", "Rising rents and strict rules", "Lack of ingredients", "Too many chefs"], answer: 1}, {q: "What must authorities do according to the text?", options: ["Ban all street vendors", "Balance public spaces and protecting small sellers", "Increase rents", "Close the food markets"], answer: 1}]},
  {id: 30, level: 2, title: "Learning a Second Language",
   text: "Learning a second language in adulthood is demanding, but it offers remarkable rewards. Adults often progress quickly in grammar and vocabulary, since they can use their existing knowledge to understand patterns. Their pronunciation, however, tends to remain influenced by their first language. Successful learners usually combine formal study with regular conversation, because speaking forces them to think in real time. Many also find that making mistakes is essential, as errors reveal what they still need to master. Adults who learn a language often benefit from setting specific goals, such as holding a ten-minute conversation about a familiar topic or reading a short news article without a dictionary. Clear goals make progress measurable and help learners stay motivated during periods when improvement feels slow. Technology can also support study, through flashcards, recorded dialogues, and language exchange partners who live abroad. Yet the most valuable practice is often the simplest: listening carefully to native speakers, noticing how they express ideas, and trying to reproduce those patterns in everyday situations, even when the result is imperfect. Learners who keep a diary of their progress, even a short one, often notice improvement that would otherwise be easy to overlook during difficult weeks.",
   questions: [{q: "What do adults often do quickly?", options: ["Pronounce perfectly", "Progress in grammar and vocabulary", "Forget their first language", "Avoid mistakes"], answer: 1}, {q: "What tends to stay influenced by the first language?", options: ["Grammar", "Vocabulary", "Pronunciation", "Reading"], answer: 2}, {q: "Why is making mistakes useful, according to the text?", options: ["It makes learners famous", "It reveals what they still need to master", "It is required by law", "It saves time"], answer: 1}]},
  {id: 31, level: 2, title: "The Problem with Plastic",
   text: "Plastic has transformed modern life, offering cheap, durable materials for packaging and countless products. Unfortunately, much of it ends up in oceans and landfills, where it can persist for centuries. Microscopic fragments now appear in drinking water, soil, and even the bodies of marine animals. Recycling helps, but only a small percentage of plastic is recycled worldwide. Many experts therefore call for reducing production, redesigning packaging, and encouraging consumers to choose reusable products whenever possible. Recycling programs differ widely from one country to another, and their effectiveness depends on local infrastructure, public participation, and the markets available for recovered materials. Some communities sort waste into many categories, while others accept most plastics in a single trash can. Researchers warn that much of what is placed in recycling bins is contaminated with food residue, which can make entire batches unusable. Better education and clearer labelling could therefore improve results. Many experts argue that the most effective strategy is to avoid unnecessary packaging altogether, since the cheapest and cleanest waste is the waste that is never created. In the end, the most sustainable package is the one that does not need to be made, and this simple idea is gaining support among designers and shoppers alike.",
   questions: [{q: "Why is plastic widely used?", options: ["It is expensive", "It is cheap and durable", "It is natural", "It is heavy"], answer: 1}, {q: "What do the microscopic fragments appear in?", options: ["Only in the air", "Drinking water and soil", "Only in cities", "Only in oceans"], answer: 1}, {q: "What do many experts call for?", options: ["Increasing production", "Reducing production and using reusable products", "Burning plastic", "Ignoring recycling"], answer: 1}]},
  {id: 32, level: 2, title: "Job Interviews Today",
   text: "Job interviews have changed considerably in recent years. Many employers now use video calls, and some include practical tasks that test real skills instead of asking only theoretical questions. Candidates are often asked to solve a problem during the interview, which allows the employer to observe their reasoning. Preparation remains important: researching the company, practicing answers aloud, and preparing thoughtful questions all help candidates stand out. Nevertheless, many recruiters admit that they still value enthusiasm and honesty above perfect answers. Interviewers often judge candidates by how they respond to unexpected questions, not only by their prepared answers. A candidate who pauses, thinks aloud, and admits uncertainty may appear more trustworthy than one who gives a rehearsed reply that sounds too polished. Preparing examples from past experience, using a clear structure such as situation, action, and result, can help candidates answer confidently. It is also wise to research the interviewers when possible, since knowing their roles and interests allows candidates to ask questions that show genuine curiosity about the position and the organization. Those who prepare thoughtfully, listen carefully, and answer with honesty usually leave a stronger impression than those who rely only on memorised phrases.",
   questions: [{q: "What have many employers started using?", options: ["Paper applications", "Video calls", "Telephone-only interviews", "Letters by mail"], answer: 1}, {q: "Why do some interviews include practical tasks?", options: ["To save money", "To test real skills", "To make candidates nervous", "To finish quickly"], answer: 1}, {q: "What do many recruiters value most, according to the text?", options: ["Perfect answers", "Enthusiasm and honesty", "Expensive clothes", "Long experience"], answer: 1}]},
  {id: 33, level: 2, title: "The History of Chocolate",
   text: "Chocolate has a history that stretches back thousands of years. The ancient peoples of Mesoamerica made a bitter drink from cacao beans, often mixed with spices and chili. Only later did Europeans add sugar and milk, transforming it into the sweet treat we know today. In the nineteenth century, new techniques made chocolate smoother and easier to produce, which helped it become affordable for ordinary people. Today the chocolate industry is global, although many farmers who grow cacao still earn very little. Chocolate production has also been affected by changing consumer preferences. Demand for dark chocolate with a high cocoa content has grown in recent years, while many buyers have become more interested in the origin of their beans. Some manufacturers now publish information about the farms that supply them and the wages paid to workers. Certification schemes attempt to guarantee fair prices and safer working conditions, although critics argue that certification alone cannot solve deep structural problems, such as the dependence of smallholders on a few large buyers and the volatility of world markets. Whether chocolate becomes a force for fairness or simply another luxury product depends on decisions made far from the factory, in the fields where the beans are grown.",
   questions: [{q: "What did ancient Mesoamerican peoples make from cacao?", options: ["A sweet cake", "A bitter drink", "A hot soup", "A dry bread"], answer: 1}, {q: "What did Europeans add later?", options: ["Salt and oil", "Sugar and milk", "Eggs and flour", "Rice and honey"], answer: 1}, {q: "What is a problem mentioned in the text?", options: ["Chocolate is illegal", "Many cacao farmers earn very little", "Chocolate has no flavor", "Factories are too small"], answer: 1}]},
  {id: 34, level: 2, title: "Urban Gardens",
   text: "In many cities, empty roofs and unused plots of land are being turned into small gardens. Residents grow vegetables, herbs, and flowers, often sharing the harvest with their neighbors. Urban gardens provide fresh food, but they also offer something less tangible: a sense of community. People who work together on a shared plot often form lasting friendships. Researchers have also observed that green spaces can reduce stress and improve air quality. For these reasons, many local governments now support the creation of community gardens. Urban gardens can also help cities adapt to climate change. Soil and vegetation absorb rainwater, reducing the burden on drains during heavy storms. Plants shade pavements and walls, which lowers the temperature of nearby surfaces. Gardens can also become outdoor classrooms, where children learn how food grows and where schools can teach science through practical activity. Many of the most successful projects are run by volunteers who organize workshops, maintain compost bins, and make sure that the produce is shared fairly among participants and local food banks. Over time, these small green spaces can transform the character of a neighbourhood, turning gray corners into places where people pause, talk, and care for one another.",
   questions: [{q: "What are empty roofs and plots being turned into?", options: ["Parking lots", "Small gardens", "Shopping centers", "Playgrounds"], answer: 1}, {q: "What is one benefit of urban gardens mentioned in the text?", options: ["They increase traffic", "They build a sense of community", "They raise rents", "They replace schools"], answer: 1}, {q: "How do local governments respond to urban gardens?", options: ["They oppose them", "They ignore them", "They support them", "They close them"], answer: 2}]},
  {id: 35, level: 2, title: "The Gig Economy",
   text: "The gig economy describes a labor market in which people work on short-term tasks rather than in permanent jobs. Drivers, couriers, and freelance designers often find work through digital platforms. This flexibility appeals to many workers who value independence and control over their schedules. However, gig workers rarely receive benefits such as paid vacations or pensions, and their income can fluctuate sharply from week to week. Policymakers now debate whether these workers should be classified as employees, a change that would give them greater protection. Gig work attracts a wide range of people, including students, parents seeking flexible hours, and professionals who want to supplement a main income. For some, the arrangement offers genuine freedom and a way to test new careers. For others, it is a necessity that comes with considerable insecurity. Unions and advocacy groups have therefore proposed minimum earnings guarantees, portable pension accounts, and better access to insurance for injuries sustained on the job. The outcome of these debates will shape how digital platforms and traditional employers compete for labor in the years ahead. Whether gig work becomes a stepping stone or a trap will depend largely on the protections that societies choose to build around it in the coming years.",
   questions: [{q: "What does the gig economy describe?", options: ["Permanent jobs with benefits", "Short-term tasks rather than permanent jobs", "Government work", "Only factory labor"], answer: 1}, {q: "What do gig workers rarely receive?", options: ["Flexible schedules", "Paid holidays and pensions", "Digital platforms", "Training courses"], answer: 1}, {q: "What would reclassifying gig workers as employees give them?", options: ["Lower taxes", "Greater protection", "More work hours", "Fewer rights"], answer: 1}]},
  {id: 36, level: 2, title: "Ancient Rome and Roads",
   text: "The Romans built an extraordinary network of roads that linked their vast empire. Many of these roads were constructed with several layers of stone and gravel, which allowed them to survive for centuries. Straight routes were preferred, even when they climbed steep hills. Along the roads, travelers found milestones, rest stops, and inns. The road network enabled soldiers to move quickly, and it also helped merchants trade goods across great distances. Some sections are still in use today, a remarkable testament to Roman engineering. The Roman road system was also remarkable for its organization. Milestones provided distances and sometimes the name of the emperor who had commissioned the work. Engineers surveyed routes carefully, drained the ground beneath the surface, and used local materials wherever possible. Maintenance was taken seriously, and local communities were often responsible for repairing sections near their settlements. This decentralised approach allowed the network to function for generations, and it shows how infrastructure can depend as much on administration and shared responsibility as on the skill of the builders themselves. Many of these roads still carry traffic today, which reminds modern engineers that durable infrastructure is built on careful planning, patient maintenance, and shared responsibility.",
   questions: [{q: "How were many Roman roads built?", options: ["With bricks only", "With several layers of stone and gravel", "With metal plates", "With wood"], answer: 1}, {q: "What kind of routes were preferred?", options: ["Winding routes", "Straight routes", "Routes through forests", "Routes along rivers"], answer: 1}, {q: "What did the road network help merchants do?", options: ["Build more roads", "Trade goods across great distances", "Avoid travel", "Hide from soldiers"], answer: 1}]},
  {id: 37, level: 2, title: "Why Bees Matter",
   text: "Bees are among the most important pollinators on Earth. Many of the fruits and vegetables we eat depend on bees to transfer pollen between flowers. Yet bee populations have declined in several regions, partly because of habitat loss, pesticides, and disease. Farmers, scientists, and gardeners are now working together to protect these insects. Planting native flowers, avoiding harmful chemicals, and providing water sources are simple steps that individuals can take. Even a small balcony with flowers can help support local bees. Beekeepers have adopted a number of practices to support colonies under stress. Some plant wildflower strips along field margins, which provide a steady supply of nectar throughout the season. Others rotate hive locations so that bees are not exposed to a single crop treated with the same chemicals year after year. Scientists also study the genetic diversity of bees, since a more varied population may resist disease more effectively. Every improvement, however small, contributes to the wider goal of keeping pollination reliable for farmers and for the wild plants that depend on insects for reproduction. Every hive that survives a season is a small victory, and every wildflower planted along a road is a quiet contribution to the health of the wider landscape.",
   questions: [{q: "What is the main role of bees described in the text?", options: ["Producing honey only", "Pollinating plants", "Building roads", "Cleaning water"], answer: 1}, {q: "What has contributed to the decline of bee populations?", options: ["More flowers", "Habitat loss, pesticides, and disease", "Too much water", "Cold winters only"], answer: 1}, {q: "What simple step can individuals take?", options: ["Building hives in cities", "Planting native flowers", "Burning leaves", "Buying more pesticides"], answer: 1}]},
  {id: 38, level: 2, title: "The Science of Habits",
   text: "Habits are behaviors that we perform automatically, often without conscious thought. According to psychologists, habits form through a loop of cue, routine, and reward. A cue, such as a certain time of day, triggers an action, and the reward reinforces it. Over time, the brain begins to anticipate the reward, making the behavior feel effortless. Changing a habit is difficult because the loop is so deeply established. Successful change usually involves replacing the routine while keeping the same cue and reward. The formation of habits also has implications for public health and education. Schools that teach students to plan their homework, to set regular study times, and to reflect on their progress may be building habits that last for decades. Health campaigns often try to create simple cues, such as keeping fruit on the kitchen table or walking after lunch, to make good choices easier to repeat. Researchers emphasize that the most effective changes are rarely dramatic. They tend to be small, consistent adjustments that become automatic over weeks and months, gradually reshaping the environment in which decisions are made. In this way, the study of habits connects individual choices with the design of schools, workplaces, and cities that either support or undermine those choices.",
   questions: [{q: "What forms a habit, according to psychologists?", options: ["A loop of cue, routine, and reward", "A single decision", "A long period of rest", "A physical injury"], answer: 0}, {q: "Why is changing a habit difficult?", options: ["The loop is deeply established", "People lack time", "Habits cannot be seen", "Rewards are missing"], answer: 0}, {q: "What does successful change usually involve?", options: ["Removing the reward", "Replacing the routine but keeping the cue and reward", "Avoiding all cues", "Forgetting the reward"], answer: 1}]},
  {id: 39, level: 2, title: "The City of Venice",
   text: "Venice is built on more than a hundred small islands in a lagoon in northern Italy. Instead of roads, the city relies on canals and bridges, and gondolas and water taxis are the main forms of transport. Over the centuries, the city has faced flooding, which threatens its historic buildings. Engineers have now designed a system of movable barriers to protect the lagoon from high tides. Critics argue the project is expensive and slow, yet most residents agree that something must be done to preserve their unique city. Venice has also developed a distinctive culture that depends on its waterways. Residents learn to navigate narrow canals on foot and by boat, and local craftspeople continue traditional trades such as glassmaking on the nearby island of Murano and gondola building in the city's workshops. Tourism brings economic opportunity, but it also places heavy pressure on housing, shops, and daily life. Many residents have moved to the mainland, leaving behind a population that is smaller and older than before. Preserving the city therefore means protecting not only its buildings but also the communities that give it meaning. The challenge for the future is to keep Venice liveable for the people who call it home, while still welcoming the visitors who admire it from around the world.",
   questions: [{q: "How is Venice mostly connected?", options: ["By highways", "By canals and bridges", "By railways", "By airplanes"], answer: 1}, {q: "What threatens the city's historic buildings?", options: ["Earthquakes", "Flooding", "Fires", "Strong winds"], answer: 1}, {q: "What do most residents think?", options: ["The project should be canceled", "Something must be done", "The city should be abandoned", "Nothing is wrong"], answer: 1}]},
  {id: 40, level: 2, title: "The Importance of Reading",
   text: "Reading for pleasure appears to offer benefits that extend far beyond entertainment. Studies suggest that people who read regularly tend to have a larger vocabulary and stronger analytical skills. Reading fiction may also improve empathy, because it allows readers to imagine the thoughts and feelings of others. In an age of constant notifications, however, many people find it difficult to concentrate on a long text. Developing the habit of reading, even for twenty minutes a day, can gradually rebuild that capacity for sustained attention. Reading for pleasure also changes how people approach unfamiliar ideas. Readers who spend time with novels, histories, and biographies become accustomed to following long arguments and to holding several viewpoints in mind at once. This habit carries over into conversations at work and in public life, where people are more willing to listen before they judge. Schools have taken notice, and many now set aside time for independent reading in the daily timetable. Teachers report that students who read widely tend to write more clearly, because they have absorbed the rhythms of well-constructed sentences without needing to memorise rules. Reading, in this sense, is not only a private pleasure but also a training ground for the patient, open-minded thinking that a democratic society needs from its citizens.",
   questions: [{q: "What do studies suggest about regular readers?", options: ["They have smaller vocabularies", "They tend to have larger vocabularies", "They never use the internet", "They are always tired"], answer: 1}, {q: "How might reading fiction help?", options: ["By improving empathy", "By increasing salary", "By saving money", "By lowering stress only"], answer: 0}, {q: "What is suggested as a way to rebuild concentration?", options: ["Reading for twenty minutes a day", "Watching more notifications", "Avoiding all books", "Reading only at night"], answer: 0}]},
  {id: 41, level: 2, title: "The Electric Car",
   text: "Electric cars are becoming increasingly popular, although they still represent a small share of total vehicle sales. Their main advantage is that they produce no exhaust emissions while driving, which improves local air quality. Their running costs are often lower than those of gas-powered cars, since electricity is usually cheaper than fuel. However, batteries are expensive to produce, and charging infrastructure remains limited in many areas. Environmental experts stress that the overall benefit depends on how the electricity itself is generated. Electric cars also raise questions about the materials needed for their batteries. Lithium, nickel, and cobalt must be mined, refined, and transported before a battery can be assembled, and each of these stages has environmental and social costs. Manufacturers are therefore investing in recycling systems that can recover valuable metals from old batteries, reducing the need for new mining. Governments support these efforts through incentives for purchasers and rules that require producers to take responsibility for batteries at the end of their useful life. The shift to electric transport is most convincing when the whole supply chain is considered, not only the vehicle on the road. Whether the switch to electric cars delivers its promise will depend on how carefully societies manage the materials, the energy, and the people behind every battery.",
   questions: [{q: "What is the main advantage of electric cars mentioned in the text?", options: ["They are very large", "They produce no exhaust while driving", "They are always cheap to buy", "They never need repairs"], answer: 1}, {q: "What do environmental experts say the overall benefit depends on?", options: ["The color of the car", "How the electricity is generated", "The speed of the car", "The size of the road"], answer: 1}, {q: "What is a limitation mentioned in the text?", options: ["Batteries are expensive and charging is limited", "Cars are too fast", "Electricity is too expensive", "Drivers are not allowed to travel"], answer: 0}]},
  {id: 42, level: 2, title: "A Letter to the Editor",
   text: "Dear Editor, I am writing to express my concern about the proposed closure of the public library in our town. The library is more than a collection of books. It hosts reading groups for children, offers computer courses for older residents, and provides a quiet place for students to study. Closing it would save money in the short term, but the long-term social cost would be considerable. I urge the council to reconsider and to explore alternative ways of reducing expenses. Libraries have also adapted to changing habits of reading and research. Many now offer e-books, online databases, and access to digital archives, alongside their traditional collections. They host workshops on digital skills, job searching, and language learning, and they provide spaces where people without internet access at home can use computers. Librarians increasingly act as guides who help visitors evaluate information critically, a role that becomes more important as false or misleading material spreads quickly online. For many residents, the library remains one of the few free public institutions in their community. Without these services, the library would be far less than a building full of books, and its closure would leave many residents without a place to learn and belong.",
   questions: [{q: "What is the writer concerned about?", options: ["A new road", "The closure of the library", "Rising taxes", "A school strike"], answer: 1}, {q: "What services does the library offer, according to the letter?", options: ["Only book loans", "Reading groups, computer courses, and a quiet study place", "Sports facilities", "Medical care"], answer: 1}, {q: "What does the writer urge the council to do?", options: ["Close the library quickly", "Reconsider and explore alternatives", "Build a new library", "Ignore residents"], answer: 1}]},
  {id: 43, level: 2, title: "The Coffee Economy",
   text: "Coffee is one of the most traded commodities in the world, and its prices can change dramatically from one season to another. Climate, disease, and political instability in producing countries all affect supply. Farmers, however, often receive only a small share of the final price that consumers pay in cafés. Some companies now offer direct trade arrangements, paying producers more in exchange for higher quality beans. Supporters believe this model gives farmers greater stability, while critics question whether it reaches the majority of growers. Coffee cultivation also has a long history of exploitation, and the modern movement for fairer trade has attempted to address it. Cooperatives of growers pool their harvests, which gives them more bargaining power and access to credit for equipment and training. Some buyers commit to purchasing a fixed share of a cooperative's output at a minimum price, while others fund community projects such as schools and clean water systems. These efforts do not remove the volatility of world markets, but they can help growers plan ahead and invest in quality rather than simply accepting whatever price is offered. Whether the cooperatives can change the balance of power in the coffee trade will depend on their ability to reach growers who remain outside their networks.",
   questions: [{q: "What affects the supply of coffee?", options: ["Only the price of sugar", "Climate, disease, and political instability", "Only consumers", "Only cafés"], answer: 1}, {q: "What do farmers often receive?", options: ["The highest share of the price", "Only a small share of the final price", "The entire price", "Nothing at all"], answer: 1}, {q: "What do critics question about direct trade?", options: ["Whether it reaches most growers", "Whether coffee is tasty", "Whether cafés are open", "Whether beans grow"], answer: 0}]},
  {id: 44, level: 2, title: "Mountain Rescue",
   text: "Mountain rescue teams are often made up of volunteers who train for many years. They must master navigation, first aid, and the use of specialized equipment such as ropes and stretchers. When an emergency call arrives, rescuers must assess the risks carefully before setting out, because bad weather can turn a rescue into a second emergency. Many teams also educate hikers about preparation, urging them to check forecasts, carry warm clothing, and inform someone of their route before leaving. Mountain rescue also depends on the coordination between volunteers, emergency services, and local authorities. Teams keep detailed records of previous incidents, which helps them identify routes that are particularly dangerous in certain conditions. They practice regularly with helicopters and with radio systems, since communication failures can slow a rescue dramatically. After each operation, teams usually hold a debriefing to discuss what went well and what could be improved. These reviews have led to changes in equipment, training, and the way rescuers approach difficult terrain at night and in poor visibility. Every successful rescue begins long before the call arrives, with training, preparation, and the hard-won knowledge of how mountains behave in different weather.",
   questions: [{q: "Who often makes up mountain rescue teams?", options: ["Paid professionals only", "Volunteers", "Soldiers only", "Doctors only"], answer: 1}, {q: "Why must rescuers assess risks carefully?", options: ["Because bad weather can create a second emergency", "Because the equipment is heavy", "Because the mountains are small", "Because teams are paid by the hour"], answer: 0}, {q: "What advice do rescue teams give hikers?", options: ["Hike alone at night", "Check forecasts and inform someone of the route", "Avoid warm clothing", "Ignore the weather"], answer: 1}]},
  {id: 45, level: 2, title: "The Ethics of Advertising",
   text: "Advertising shapes the way we see products, brands, and even ourselves. Its defenders argue that it informs consumers about new options and supports the economy that funds free media. Critics, however, point out that advertisements often exploit insecurities, encouraging people to buy things they do not need. Children are particularly vulnerable, since they struggle to distinguish commercial messages from entertainment. Many countries now restrict certain forms of advertising aimed at young audiences, although the debate about where to draw the line continues. Critics of advertising to children often point to research showing that young people struggle to recognize persuasive intent before a certain age. Some countries have responded by limiting advertising during children's programs and by banning certain marketing techniques, such as using cartoon characters to sell sugary products. Advertisers counter that such restrictions may push brands into less transparent channels. Regulators therefore face the challenge of protecting children without making it impossible for legitimate businesses to communicate with families about the products they offer and the choices available. Ultimately, the goal is to create advertising that informs rather than manipulates, so that young people can grow up with a healthy sense of their own choices.",
   questions: [{q: "What do defenders of advertising argue?", options: ["It informs consumers and supports the economy", "It is always harmful", "It should be banned", "It only sells cars"], answer: 0}, {q: "What do critics say advertisements often exploit?", options: ["Consumers' sleep", "Insecurities", "Free media", "Public parks"], answer: 1}, {q: "Why are children particularly vulnerable?", options: ["They have a lot of money", "They struggle to tell advertising from entertainment", "They never watch television", "They enjoy shopping alone"], answer: 1}]},
  {id: 46, level: 2, title: "Museums and Visitors",
   text: "Museums face a difficult balance between preserving fragile artifacts and making them accessible to the public. Many institutions have begun to digitize their collections, allowing people around the world to explore objects from a distance. Yet digital displays cannot fully replace the experience of standing before an original painting or sculpture. Some museums therefore design interactive exhibitions that encourage visitors to touch replicas, ask questions, and participate in discussions. Such approaches aim to make the visit memorable rather than merely educational. Museums have also experimented with new forms of visitor engagement, such as audio guides that tell stories from the perspective of people connected to the objects, and exhibitions designed for visitors with sight or hearing impairments. Many institutions now consult with the communities whose heritage they display, recognizing that the meaning of an artifact can change depending on who interprets it. Some museums have also returned objects acquired under unjust circumstances, a process that requires careful negotiation, historical research, and a willingness to rethink long-standing assumptions about ownership. Each new visitor who leaves a museum with a question in mind has been given something valuable, and this is perhaps the most important measure of success.",
   questions: [{q: "What is the difficult balance museums face?", options: ["Between prices and staff", "Between preserving artifacts and making them accessible", "Between old and new cities", "Between paintings and music"], answer: 1}, {q: "What can digital displays not fully replace?", options: ["The internet", "The experience of seeing an original", "The museum guide", "The entrance fee"], answer: 1}, {q: "What do interactive exhibitions aim to do?", options: ["Make the visit memorable", "Reduce the number of visitors", "Close the museum", "Sell replicas only"], answer: 0}]},
  {id: 47, level: 2, title: "The Future of Work",
   text: "Automation is transforming many industries, and some analysts predict that millions of routine jobs will disappear over the coming decade. Yet history suggests that technological change also creates new occupations that were previously unimaginable. The challenge for governments and educators is to prepare workers for roles that require creativity, complex communication, and adaptability. Lifelong learning, rather than a single qualification, is likely to become the norm. Those who continue to develop their skills may find that they can move between sectors with greater ease. The changing nature of work also affects how people plan their education. Students increasingly combine formal study with short courses, professional certificates, and online programs that can be completed alongside a job. Employers have begun to recognize these credentials, especially when they are linked to specific skills that can be demonstrated in practice. Universities respond by offering modular programs and recognition of prior learning. The result is a more flexible system in which a person may return to study several times during a career, rather than completing all of their education at the beginning of adult life. Workers who keep learning throughout their lives will be better placed to adapt, not because they can predict the future, but because they can change direction when it arrives.",
   questions: [{q: "What do some analysts predict?", options: ["That all jobs will be created", "That millions of routine jobs will disappear", "That workers will retire earlier", "That automation will stop"], answer: 1}, {q: "What skills are mentioned as important for future roles?", options: ["Speed and strength", "Creativity, communication, and adaptability", "Only mathematics", "Physical endurance"], answer: 1}, {q: "What is likely to become the norm?", options: ["One qualification for life", "Lifelong learning", "Working only from home", "Short working weeks only"], answer: 1}]},
  {id: 48, level: 2, title: "A Lost Language",
   text: "Every year, linguists record the disappearance of languages spoken by only a handful of elderly people. When a language vanishes, a unique way of understanding the world is lost with it, including specific vocabulary for plants, animals, and natural phenomena. Some communities are working to revive their languages through schools, songs, and digital recordings. Their efforts show that language is not simply a tool for communication but also an expression of identity and memory. Language loss is not inevitable, and several communities have succeeded in strengthening their languages. Immersion schools teach children entirely in the endangered language during their early years, while adult courses help parents and grandparents relearn words they had not used for decades. Recording elders telling traditional stories creates resources that future generations can study and enjoy. The most important factor, however, is often the daily use of the language at home and in community gatherings, since languages survive when people choose to speak them for ordinary purposes rather than only for ceremonies. Each language that is recovered adds another perspective to human knowledge, and every child who learns a traditional word helps keep an old way of seeing the world alive.",
   questions: [{q: "What happens to languages that are spoken by only a few elderly people?", options: ["They become popular", "They disappear", "They are translated automatically", "They grow stronger"], answer: 1}, {q: "What is lost when a language vanishes, according to the text?", options: ["Only grammar books", "A unique way of understanding the world", "Only dictionaries", "Only songs"], answer: 1}, {q: "How are some communities trying to revive their languages?", options: ["By banning other languages", "Through schools, songs, and digital recordings", "By moving away", "By ignoring the younger generation"], answer: 1}]},
  {id: 49, level: 2, title: "The Benefits of Walking",
   text: "Walking is one of the simplest forms of exercise, yet its benefits are considerable. Regular walks can lower blood pressure, strengthen the heart, and help control weight. Many people also report improved mood after a walk, perhaps because fresh air and gentle movement reduce stress. Urban planners increasingly design cities with pedestrians in mind, adding wider pavements, shaded paths, and safer crossings. Such changes encourage residents to walk more often, which benefits both individuals and the wider community. Walking also supports mental wellbeing in less obvious ways. Walking with another person can make conversation easier and create a sense of shared experience, which strengthens social ties. Walking in green spaces has been linked to improved attention, since natural scenes allow the mind to rest from the demands of screens and deadlines. Many people also use walks to think through problems, and some describe their most creative ideas as arriving while moving through a park or along a river. For older adults, regular walking can help maintain balance and independence. Simple movement, taken every day, can therefore be one of the most accessible and effective ways to protect both body and mind throughout a long life.",
   questions: [{q: "What can regular walks help lower?", options: ["Blood pressure", "Happiness", "Salary", "Sleep time"], answer: 0}, {q: "Why do many people feel better after a walk?", options: ["Because they eat more", "Because fresh air and movement reduce stress", "Because they sleep longer", "Because they travel faster"], answer: 1}, {q: "What are urban planners adding to encourage walking?", options: ["Highways", "Wider pavements, shaded paths, and safer crossings", "Parking garages", "Fast trains"], answer: 1}]},
  {id: 50, level: 2, title: "Fast Fashion",
   text: "Fast fashion refers to inexpensive clothing that is designed, produced, and sold at great speed. Retailers release new collections almost every week, encouraging consumers to buy more and wear items for only a short time. The environmental impact is substantial, since production requires large amounts of water and energy, and garments are often discarded after few uses. Labor conditions in some factories have also attracted criticism. Consumers who want to reduce their footprint are increasingly choosing second-hand clothing, repairing old items, or buying from brands that commit to transparency. Fast fashion has also contributed to the growth of clothing waste. Garments made from synthetic fibres can take decades to break down, and many items that are donated to charity shops are exported to countries that lack the capacity to sell or recycle them. Some designers now experiment with fabrics made from recycled materials, and a small number of brands offer repair services or take back old clothes for reuse. Governments are also discussing extended producer responsibility, which would require companies to pay for the collection and treatment of the products they sell. Ultimately, the most responsible choice is often to buy less, keep what we own for longer, and ask whether a garment's true cost has been fairly shared.",
   questions: [{q: "What does fast fashion refer to?", options: ["Expensive designer clothing", "Inexpensive clothing made and sold quickly", "Traditional hand-made clothes", "Clothing for children only"], answer: 1}, {q: "Why does fast fashion have a large environmental impact?", options: ["It uses no water", "It requires much water and energy and clothes are discarded quickly", "It is made only of paper", "It is sold only online"], answer: 1}, {q: "What do some consumers choose to reduce their footprint?", options: ["Buying more new clothes", "Second-hand clothing and repairing old items", "Throwing clothes away", "Shopping only at night"], answer: 1}]},
  {id: 51, level: 3, title: "The Paradox of Choice",
   text: "Conventional wisdom holds that the more options we have, the better our decisions will be. Yet a body of research suggests otherwise. When confronted with an overwhelming array of alternatives, people often experience paralysis rather than liberation, postponing decisions altogether or settling for suboptimal choices. Moreover, having too many options can heighten post-decision regret, since the abundance of unchosen possibilities makes the selected one appear less satisfactory. The implication is not that choice should be eliminated, but that curating options thoughtfully may serve consumers better than sheer abundance. Choice overload also affects how people feel after a decision is made. Shoppers who choose from a small selection often report greater satisfaction with their purchase, partly because they can imagine the alternatives more clearly. Those who face a huge range may spend time wondering whether a different product would have been better, which weakens their enjoyment of the item they actually bought. Retailers have begun to exploit this insight by offering curated collections and clear recommendations, while still allowing customers to explore a wider catalog when they wish to do so. Ultimately, the paradox teaches a practical lesson: the goal is not to reduce choice to nothing, but to design environments in which people can decide with confidence and calm.",
   questions: [{q: "What does conventional wisdom claim?", options: ["Fewer options always lead to regret", "More options lead to better decisions", "Choices should be avoided", "Decisions are always easy"], answer: 1}, {q: "What does too many options often cause, according to the research?", options: ["Liberation", "Paralysis", "Higher income", "Faster decisions"], answer: 1}, {q: "What is the implication the author draws?", options: ["Choice should be eliminated", "Curating options thoughtfully may serve consumers better", "Abundance is always preferable", "Decisions should be postponed"], answer: 1}]},
  {id: 52, level: 3, title: "The Ethics of Gene Editing",
   text: "The advent of precise gene-editing technologies has prompted profound ethical deliberation. Therapeutic applications, such as correcting mutations responsible for devastating hereditary diseases, are widely regarded as laudable. Enhancement, however, provokes considerable unease: would altering traits such as intelligence or stature exacerbate existing inequalities? Critics also caution that germline modifications, which are inherited by future generations, cannot be easily reversed should unforeseen consequences emerge. Consequently, many bioethicists advocate a rigorous, internationally coordinated framework rather than an unregulated race toward innovation. Gene editing also raises questions about consent and fairness in research. Patients who take part in early trials may face uncertain benefits and unknown risks, and their willingness to participate can be influenced by desperation or by the expectations of their doctors. Research ethics committees therefore review protocols carefully, ensuring that participants understand what is known and what remains uncertain. Public engagement is equally important, since decisions about powerful technologies should not be made only by scientists, companies, and governments, but also by the citizens who will live with their consequences. Ultimately, the challenge is to combine scientific ambition with humility, recognizing that the power to change the living world carries obligations that no laboratory can meet alone.",
   questions: [{q: "Which application of gene editing is widely regarded as laudable?", options: ["Enhancing intelligence", "Correcting hereditary disease mutations", "Changing physical stature", "Creating new species"], answer: 1}, {q: "Why are germline modifications a particular concern?", options: ["They are very expensive", "They are inherited and hard to reverse", "They are easy to detect", "They only affect adults"], answer: 1}, {q: "What do many bioethicists advocate?", options: ["An unregulated race", "A rigorous, internationally coordinated framework", "A complete ban on research", "Private control of the technology"], answer: 1}]},
  {id: 53, level: 3, title: "The Anthropology of Gift Exchange",
   text: "In many societies, the exchange of gifts constitutes far more than a simple transaction. Anthropologists have long observed that reciprocity creates enduring social bonds, obliging recipients to respond in kind at a later date. Such obligations are seldom explicit; instead, they are sustained through a tacit understanding that generosity will eventually be returned. Marcel Mauss famously argued that gifts carry an implicit spirit that compels reciprocation. Although modern market economies have largely separated commerce from kinship, the sentiment of obligation lingers in ceremonies such as weddings, where guests' contributions effectively function as a form of deferred reciprocity. Anthropologists have also studied how gift exchange operates in contexts far removed from traditional societies, including online communities, open-source software projects, and charitable networks. In these settings, contributors often give time, knowledge, or resources without expecting immediate payment, yet they may still anticipate recognition, reciprocal help, or a sense of belonging. Such examples suggest that generosity and obligation are not opposites. Instead, they interact in complex ways that continue to shape cooperation, reputation, and trust in contemporary life. Ultimately, the anthropology of gifts reminds us that economies are never purely mechanical, because they are sustained by relationships, memories, and the quiet expectation that kindness will be remembered.",
   questions: [{q: "What do gift exchanges create, according to anthropologists?", options: ["Financial debts", "Enduring social bonds", "Legal contracts", "Competitive rivalries"], answer: 1}, {q: "How are reciprocal obligations usually sustained?", options: ["Through written agreements", "Through a tacit understanding", "Through public laws", "Through formal penalties"], answer: 1}, {q: "What does the text suggest about wedding gifts?", options: ["They are purely commercial", "They function as deferred reciprocity", "They are forbidden", "They are unrelated to obligation"], answer: 1}]},
  {id: 54, level: 3, title: "Urban Heat Islands",
   text: "Cities are frequently several degrees warmer than their rural surroundings, a phenomenon known as the urban heat island effect. Its causes are multifaceted: dark asphalt and concrete absorb and retain solar radiation, while the scarcity of vegetation diminishes evapotranspirative cooling. Waste heat from vehicles and air conditioning compounds the problem. The consequences extend beyond discomfort, exacerbating heat-related mortality among vulnerable populations and intensifying energy demand. Planners increasingly counter the effect through green roofs, reflective surfaces, and an expanded urban canopy, interventions that mitigate heat while enhancing biodiversity. Urban heat islands also affect the health of workers who spend long hours outdoors, such as builders, delivery drivers, and street vendors. For these groups, extreme temperatures can cause dehydration, exhaustion, and heat stroke, sometimes with fatal results. Cities respond with measures like shaded bus stops, cooling centers in libraries and community halls, and rules that limit outdoor work during the hottest hours. Such measures are most effective when they are planned with the people who experience the heat most directly, since their knowledge reveals where protection is most urgently needed. Ultimately, cities that wish to cool their streets must treat heat as a shared social problem, one that requires coordination between planners, engineers, residents, and public health officials.",
   questions: [{q: "What is the urban heat island effect?", options: ["Cities being cooler than rural areas", "Cities being several degrees warmer than rural surroundings", "Rural areas becoming urbanised", "Heat waves moving into the countryside"], answer: 1}, {q: "Why does vegetation matter in this context?", options: ["It absorbs sound", "It supports evapotranspirative cooling", "It generates waste heat", "It reflects sunlight entirely"], answer: 1}, {q: "Which intervention is NOT mentioned as a countermeasure?", options: ["Green roofs", "Reflective surfaces", "Expanded urban canopy", "Increasing asphalt coverage"], answer: 3}]},
  {id: 55, level: 3, title: "The Dilemma of Expertise",
   text: "Expertise is indispensable, yet it can paradoxically hinder innovation. Experts accumulate knowledge that enables them to recognize patterns quickly, but this very efficiency can blind them to anomalies that fall outside established frameworks. Psychologists describe this as the curse of knowledge: once one understands something deeply, it becomes difficult to imagine the perspective of a novice. Organizations therefore benefit from deliberately incorporating outsiders, whose unfamiliarity with prevailing assumptions allows them to question premises that insiders have long taken for granted. The concept of expertise is also tested in fields where knowledge changes rapidly. Medicine, technology, and economics produce new findings constantly, and professionals must update their understanding throughout their careers. Experts who remain open to revision can benefit from new evidence, while those who cling to outdated methods may lose their advantage. Professional communities therefore invest in continuing education, peer review, and structured reflection, aiming to keep expertise responsive rather than frozen. The ideal is confidence grounded in evidence, not confidence that resists being proved wrong. Ultimately, the expert's greatest strength may lie in knowing where their knowledge ends, and in welcoming questions that come from people who see the problem from another angle.",
   questions: [{q: "What paradox does the text describe about experts?", options: ["Experts are always wrong", "Expertise can hinder innovation", "Experts never recognize patterns", "Experts are unnecessary"], answer: 1}, {q: "What is the curse of knowledge?", options: ["Forgetting facts", "Difficulty imagining a novice's perspective", "A lack of education", "Fear of learning"], answer: 1}, {q: "Why do organizations benefit from outsiders?", options: ["They are cheaper", "They question assumptions insiders take for granted", "They work faster", "They know more facts"], answer: 1}]},
  {id: 56, level: 3, title: "Sovereign Debt and Austerity",
   text: "Governments confronted with mounting sovereign debt frequently resort to austerity, curtailing public expenditure to restore fiscal credibility. Proponents contend that restraint reassures creditors and forestalls a more acute crisis. Critics, by contrast, argue that abrupt contraction depresses aggregate demand, deepening recession and ironically enlarging the very debt-to-GDP ratio the policy seeks to reduce. The empirical record is contested, with outcomes depending heavily on monetary conditions, the composition of cuts, and the structure of the economy. Consequently, the debate rarely resolves into a simple verdict on whether austerity works. Debt crises also reveal political choices about who bears the cost of adjustment. Governments may protect bondholders and banks, or they may prioritize pensioners, public workers, and vulnerable families. Each decision reflects a set of values about fairness and responsibility, and each shapes the social fabric for years afterward. Historians note that societies which negotiated adjustments transparently and distributed burdens widely often recovered with less lasting resentment than those where the costs fell disproportionately on the least powerful groups. Ultimately, the debate reminds us that economic recovery is not only a matter of numbers, but also of the trust that citizens place in the fairness of the sacrifices they are asked to make.",
   questions: [{q: "Why do governments resort to austerity?", options: ["To increase public spending", "To restore fiscal credibility", "To reduce taxes to zero", "To expand the welfare state"], answer: 1}, {q: "What do critics argue about abrupt contraction?", options: ["It reassures creditors", "It deepens recession and can enlarge the debt ratio", "It has no effect on demand", "It eliminates inflation"], answer: 1}, {q: "What does the text say about the empirical evidence?", options: ["It is clear and unanimous", "It is contested and depends on several conditions", "It shows austerity always works", "It is entirely unavailable"], answer: 1}]},
  {id: 57, level: 3, title: "The Limits of Translation",
   text: "Translation is commonly regarded as a mechanical substitution of words, yet practitioners know that equivalence is elusive. Languages partition experience differently: a single term in one tongue may encompass a range of meanings that another language divides into several distinct words. Idioms, cultural references, and rhythm further complicate the task. Translators must therefore make calculated compromises, privileging fidelity to meaning, tone, or readability depending on the purpose of the text. Far from being a lesser form of writing, skilled translation is an act of interpretation that demands both linguistic and cultural sensitivity. Translators also face practical constraints that shape their work. Deadlines are often tight, fees may be modest, and clients may request a particular style that conflicts with the original author's voice. Professional bodies have responded by promoting standards for accuracy, confidentiality, and ethical conduct, and by encouraging translators to negotiate fair terms. Many translators also collaborate with editors and subject specialists, recognizing that a text about medicine, law, or engineering requires precision that general linguistic skill alone cannot provide. Ultimately, the translator's task is not to erase the foreign text, but to build a bridge that allows readers to cross it while still feeling the distance between two worlds.",
   questions: [{q: "How is translation commonly regarded?", options: ["As a complex art", "As a mechanical substitution of words", "As unnecessary", "As a form of speech"], answer: 1}, {q: "Why is equivalence elusive?", options: ["Because languages divide experience differently", "Because translators are lazy", "Because dictionaries are missing", "Because texts are too short"], answer: 0}, {q: "What does the author say skilled translation demands?", options: ["Only grammar", "Linguistic and cultural sensitivity", "Speed above all", "Literal word-for-word replacement"], answer: 1}]},
  {id: 58, level: 3, title: "Reforming Public Institutions",
   text: "Public institutions are often criticized for their inertia, a tendency to preserve procedures long after their original rationale has dissipated. Reform efforts, though frequently announced with fanfare, tend to founder on entrenched interests and the sheer complexity of coordinating disparate agencies. Successful transformations typically share certain characteristics: a clear and widely communicated purpose, sustained leadership over several years, and mechanisms that reward experimentation rather than punish failure. Without these elements, reorganisations merely reshuffle responsibilities while leaving the underlying culture intact. Reform efforts often benefit from an honest assessment of what has already been tried. Leaders who acknowledge past failures signal that they are not simply repeating earlier promises under a new name. Pilot projects can then test ideas on a small scale before they are extended across an entire organization. Feedback from frontline staff is particularly valuable, since those closest to daily operations often identify practical obstacles that remote planners overlook. Without such learning, reforms risk becoming cycles of announcement and disappointment, leaving employees increasingly skeptical about each new initiative. Ultimately, reform succeeds when institutions learn to see their own habits clearly, to question what they have always done, and to make room for those who propose better ways.",
   questions: [{q: "What is public institutions' often-criticized tendency?", options: ["Excessive speed", "Inertia", "Excessive innovation", "Frequent elections"], answer: 1}, {q: "Why do reform efforts often founder?", options: ["Because they are too cheap", "Because of entrenched interests and coordination complexity", "Because citizens refuse to pay", "Because leaders retire quickly"], answer: 1}, {q: "What do successful transformations typically include?", options: ["Punishment for failure", "Sustained leadership and rewards for experimentation", "Short-term budgets only", "Frequent reorganisations"], answer: 1}]},
  {id: 59, level: 3, title: "The Psychology of Procrastination",
   text: "Procrastination is frequently misconstrued as a simple failure of discipline. Contemporary research, however, locates its roots in emotion regulation: individuals postpone tasks that provoke anxiety, boredom, or self-doubt in pursuit of immediate mood relief. The pattern is self-reinforcing, since avoidance yields temporary comfort while intensifying the subsequent pressure. Interventions that address the emotional dimension, such as breaking tasks into smaller components or reframing their meaning, often prove more effective than exhortations to simply try harder. Procrastination also has social dimensions. People sometimes delay tasks because they fear that others will judge the result, and they may prefer the uncertainty of waiting to the discomfort of receiving criticism. Teams can reduce this pressure by normalising drafts, celebrating partial progress, and framing feedback as a step in a shared process. Some researchers suggest that committing publicly to a deadline, or agreeing on a small first step with a colleague, can make action feel less daunting and more achievable, particularly for tasks that seem vague or overwhelming at first. Ultimately, overcoming procrastination is less about willpower than about making the next step smaller, kinder, and more honest about the feelings that accompany it.",
   questions: [{q: "How is procrastination frequently misconstrued?", options: ["As an emotional problem", "As a simple failure of discipline", "As a medical condition", "As a form of creativity"], answer: 1}, {q: "According to research, what does procrastination relate to?", options: ["Physical strength", "Emotion regulation", "Income level", "Memory capacity"], answer: 1}, {q: "Why are emotional interventions often more effective?", options: ["They are faster", "They address the emotional dimension rather than just demanding effort", "They require no effort at all", "They avoid all tasks"], answer: 1}]},
  {id: 60, level: 3, title: "The Myth of the Lone Genius",
   text: "The popular image of the solitary genius, toiling in isolation until a revolutionary idea emerges, has proved remarkably durable. Historians of science, however, have increasingly demonstrated that breakthroughs typically arise from networks of correspondence, collaboration, and competition. Ideas circulate, are refined through criticism, and are often discovered simultaneously by several researchers. The lone genius narrative flatters the individual while obscuring the collective infrastructure on which creativity depends. Recognizing this does not diminish achievement; rather, it situates brilliance within a richer social context. The myth of the lone genius also shapes how students are taught. Textbooks often present scientific discoveries as sudden flashes of insight, leaving out the years of preparation, the failed experiments, and the colleagues whose ideas made the final breakthrough possible. Educators who wish to correct this picture can use case studies that show the messy process of discovery, the disagreements that shaped it, and the ways in which ideas were challenged and revised. Such accounts can encourage students to see creativity as something that grows through collaboration and persistence. Ultimately, the lone genius myth should give way to a more accurate picture, one in which individual brilliance and collective effort are understood as partners rather than rivals.",
   questions: [{q: "What popular image does the text criticize?", options: ["A team of scientists", "The solitary genius working alone", "A computer programmer", "A government official"], answer: 1}, {q: "How do historians describe the origin of breakthroughs?", options: ["As singular accidents", "As arising from networks of correspondence and collaboration", "As products of luck alone", "As secrets kept by individuals"], answer: 1}, {q: "What does recognizing the collective nature of creativity do, according to the author?", options: ["It diminishes achievement", "It situates brilliance within a richer social context", "It eliminates competition", "It proves genius is fake"], answer: 1}]},
  {id: 61, level: 3, title: "Coral Reefs Under Pressure",
   text: "Coral reefs, which occupy less than one percent of the ocean floor, sustain roughly a quarter of marine species. Their fragility, however, is increasingly apparent. Rising sea temperatures provoke bleaching, a process in which corals expel the symbiotic algae that provide much of their nourishment. Acidification, driven by absorbed carbon dioxide, further impairs their capacity to build skeletons. Local pressures such as overfishing and pollution compound these global threats. Although restoration projects show promise, scientists caution that without substantial reductions in emissions, even the most ambitious interventions may prove insufficient. Coral reefs also provide practical benefits to people who live near them. They protect coastlines from storm waves, reducing erosion and flood damage, and they support fishing industries that feed millions of people. Reefs attract tourists who come to snorkel and dive, creating jobs in hospitality and local transport. Losing reefs would therefore affect food security, livelihoods, and the resilience of coastal communities, which is why many local governments now include reef protection in their long-term planning and in agreements with neighbouring countries. Ultimately, the reefs remind us that ecosystems and human prosperity are deeply intertwined, and that protecting one often means protecting the other for future generations.",
   questions: [{q: "What proportion of marine species do reefs sustain?", options: ["Less than one percent", "Roughly a quarter", "Nearly all", "Half"], answer: 1}, {q: "What causes bleaching?", options: ["Excess sunlight alone", "Rising sea temperatures causing corals to expel algae", "Heavy rainfall", "Strong currents"], answer: 1}, {q: "What do scientists caution about restoration?", options: ["It is always successful", "It may be insufficient without reducing emissions", "It is too cheap", "It has no effect"], answer: 1}]},
  {id: 62, level: 3, title: "The Ambiguity of Language",
   text: "Ambiguity is often treated as a defect in language, yet it is equally a source of richness. Puns, double entendres, and deliberately polysemous expressions exploit the capacity of words to carry several meanings simultaneously. Poets have long relied on such plurality to generate layers of resonance. In legal and technical contexts, by contrast, ambiguity is hazardous, and drafters strive for precision. The skill lies in recognizing which register demands clarity and which rewards interpretive openness. Ambiguity also appears frequently in everyday conversation, where speakers rely on context, tone, and shared knowledge to resolve meaning. A remark such as \"that's interesting\" may express enthusiasm, polite doubt, or mild disapproval, depending on how it is said and what came before it. Listeners usually interpret these signals without difficulty, yet automated systems that process language often struggle with them. This gap is one reason why developers of language technology study pragmatics, the branch of linguistics concerned with how meaning depends on the situation in which words are used. Ultimately, ambiguity is neither a flaw nor a gift in itself; its value depends on the purpose of the words and on the willingness of listeners to explore what lies beyond the first meaning.",
   questions: [{q: "How is ambiguity often treated?", options: ["As a defect", "As a strength only", "As irrelevant", "As a legal requirement"], answer: 0}, {q: "What do poets use plurality for?", options: ["To create layers of resonance", "To avoid meaning", "To write contracts", "To shorten sentences"], answer: 0}, {q: "Where is ambiguity hazardous?", options: ["In poetry", "In legal and technical contexts", "In jokes", "In conversation with friends"], answer: 1}]},
  {id: 63, level: 3, title: "Sleep Deprivation and Judgment",
   text: "Sleep deprivation is frequently regarded as a matter of mere fatigue, yet its cognitive consequences can be surprisingly severe. Studies indicate that a night of severely restricted sleep can impair judgment to a degree comparable to moderate intoxication. Individuals often underestimate this decline, a phenomenon that may be particularly hazardous in occupations requiring vigilance, such as surgery or long-haul driving. Because the sense of impairment itself diminishes, people can feel confident while performing poorly, which makes systematic safeguards more valuable than personal self-assessment alone. Sleep deprivation also affects the way people evaluate risk. Tired individuals may underweight the dangers of an action while overestimating their own ability to manage it. This combination can lead to decisions that seem reasonable in the moment but prove costly later. Organizations that rely on extended working hours, such as emergency services, transport operators, and hospitals, therefore increasingly set limits on consecutive shifts and require rest periods between them. Such rules protect not only the workers themselves but also the people who depend on their attention. Ultimately, sleep is not a sign of weakness but a practical safeguard, and organizations that respect it protect their employees, their customers, and their own reputations at the same time.",
   questions: [{q: "How is sleep deprivation frequently regarded?", options: ["As a serious brain disorder", "As a matter of mere fatigue", "As a sign of intelligence", "As a healthy routine"], answer: 1}, {q: "What comparison does the text make?", options: ["To moderate intoxication", "To a vacation", "To physical exercise", "To a school exam"], answer: 0}, {q: "Why are systematic safeguards valuable?", options: ["Because people underestimate their impairment", "Because sleep is unnecessary", "Because surgeons are always rested", "Because fatigue is always visible"], answer: 0}]},
  {id: 64, level: 3, title: "The Economics of Attention",
   text: "In the attention economy, the scarce resource is not information but the cognitive capacity to process it. Platforms compete for user engagement, often by optimising features that exploit psychological tendencies toward novelty and social validation. The consequence is a fragmentation of focus, as users alternate rapidly between streams of stimuli. Scholars debate whether individuals can meaningfully reclaim their attention through personal discipline, or whether the structural incentives of digital markets require regulatory intervention to be substantially altered. Attention can also be understood as a form of labor. When users spend hours scrolling through feeds, they generate data and engagement that companies convert into advertising revenue. Some economists therefore describe this activity as unpaid work, in which people contribute value without compensation. Others reject the analogy, arguing that users freely choose the time they spend online. The disagreement reveals deeper questions about consent, value, and the boundaries between leisure and production in a digital economy. Ultimately, the attention economy invites a difficult question: whether the freedom to choose what we look at can be protected when the systems that compete for our gaze are so carefully designed.",
   questions: [{q: "What is the scarce resource in the attention economy?", options: ["Information itself", "Cognitive capacity to process information", "Money", "Electricity"], answer: 1}, {q: "What do platforms often exploit?", options: ["Physical strength", "Psychological tendencies toward novelty and social validation", "Written laws", "Daylight hours"], answer: 1}, {q: "What do scholars debate?", options: ["Whether personal discipline alone can reclaim attention or regulation is needed", "Whether attention exists", "Whether phones are cheap", "Whether screens are colourful"], answer: 0}]},
  {id: 65, level: 3, title: "Heritage and Authenticity",
   text: "Heritage conservation confronts a persistent dilemma: should monuments be preserved in their current state, complete with accumulated alterations, or restored to an idealised original form? Restoration can recover architectural coherence but risks imposing a contemporary interpretation on the past. Conversely, preserving a building in a condition of visible decay may honor its history yet forfeit its capacity to serve communities. Most charters now advocate minimal intervention, emphasizing reversibility and documentation, so that future generations can evaluate decisions made today. Heritage conservation also requires skills that combine scientific analysis with practical craftsmanship. Conservators use chemical testing to identify materials, microscopes to examine damage, and careful documentation to record each stage of intervention. Yet many of the most important decisions depend on judgment, since no single method can resolve every tension between authenticity and usability. Training programs increasingly emphasize ethical reasoning alongside technical expertise, preparing conservators to explain their choices to colleagues, funders, and the public. Ultimately, a heritage site is a living conversation between the past and the present, and the most faithful decisions are often those that keep this conversation open for those who follow.",
   questions: [{q: "What is the persistent dilemma described?", options: ["Whether to build new monuments", "Whether to preserve a monument as it is or restore an idealised original", "Whether to sell monuments", "Whether to ignore history"], answer: 1}, {q: "What risk does restoration carry?", options: ["Imposing a contemporary interpretation on the past", "Destroying all documentation", "Making buildings cheaper", "Ending tourism"], answer: 0}, {q: "What do most charters now advocate?", options: ["Complete reconstruction", "Minimal intervention emphasizing reversibility and documentation", "Demolition of decayed buildings", "Ignoring documentation"], answer: 1}]},
  {id: 66, level: 3, title: "Organizational Silence",
   text: "Organizations frequently suffer not from a shortage of information but from a reluctance to articulate it. Employees may withhold concerns for reasons of self-protection, perceiving that candor could jeopardise their standing. Such organizational silence is rarely deliberate; it arises from accumulated signals about which views are welcome and which are penalised. Its consequences are insidious, since problems fester unnoticed until they become crises. Leaders who wish to counter this tendency must demonstrate, through their own conduct, that dissent is treated as a contribution rather than a threat. Successful organizations also learn from the way they handle failure. Blame-focused cultures tend to hide errors, which prevents the organization from understanding their causes. By contrast, systems that treat mistakes as information encourage employees to report problems early, when they are still manageable. Some companies conduct blameless reviews after incidents, asking what conditions made the error likely rather than who should be punished. Such reviews require courage from leaders, but they often produce lasting improvements that protect both customers and staff. Ultimately, organizations that want honesty from their members must first show that candor is safe, because silence is usually the rational response to an environment that punishes bad news.",
   questions: [{q: "What do organizations often suffer from?", options: ["A shortage of information", "A reluctance to articulate information", "Too many employees", "Excessive candor"], answer: 1}, {q: "Why is organizational silence rarely deliberate?", options: ["It arises from accumulated signals about welcome views", "Employees are paid to be silent", "It is required by law", "It only affects new staff"], answer: 0}, {q: "How can leaders counter this tendency?", options: ["By punishing dissent", "By showing that dissent is treated as a contribution", "By reducing communication", "By avoiding feedback"], answer: 1}]},
  {id: 67, level: 3, title: "The Architecture of Memory",
   text: "Memory researchers have shown that recollection is not a faithful replay of past experience but an act of reconstruction. Each time we recall an event, the memory is subtly altered by present beliefs, emotions, and the cues surrounding the retrieval. This plasticity explains why eyewitness testimony can be strikingly unreliable, even when witnesses are sincere. Paradoxically, the same malleability permits learning and adaptation, since updated information can be integrated into existing knowledge structures. The challenge lies in distinguishing between useful revision and distortion. Sleep and memory are closely connected in the way the brain organizes experience. Some researchers believe that sleep helps sort important information from trivial details, strengthening the connections that matter for future use. Learners who sleep after studying often retain material better than those who remain awake, which suggests that cramming late into the night may be less effective than a balanced schedule. Teachers have begun to share these findings with students, encouraging them to plan study sessions so that rest follows learning rather than replacing it. Ultimately, memory is not a museum that stores the past intact, but a living process that helps us make sense of experience, and understanding this may make us more humble about what we think we remember.",
   questions: [{q: "How do researchers describe recollection?", options: ["As a faithful replay", "As an act of reconstruction", "As a biological accident", "As a permanent record"], answer: 1}, {q: "Why can eyewitness testimony be unreliable?", options: ["Because witnesses are dishonest", "Because memories are altered by present beliefs and cues", "Because courts ignore it", "Because memories are always accurate"], answer: 1}, {q: "What does the malleability of memory allow?", options: ["Learning and adaptation", "Complete forgetting", "Perfect recall", "Immunity to emotion"], answer: 0}]},
  {id: 68, level: 3, title: "The Politics of Infrastructure",
   text: "Infrastructure projects are rarely neutral. The placement of a highway or a rail line can determine which neighbourhoods flourish and which decline, as well as who has access to employment, schools, and green space. Historians of urban development have documented how such decisions often reflected the priorities of powerful interest groups rather than those of the communities most affected. Contemporary planners therefore increasingly emphasize participatory processes, arguing that technical efficiency alone cannot justify choices with profound distributional consequences. Public infrastructure has also been used to address inequality. Affordable public transport, well-lit streets, and safe pavements can give residents access to jobs, healthcare, and education regardless of whether they own a car. Planners who study these effects argue that transport decisions are never purely technical, because they determine how easily people can reach opportunities. Investment in neglected areas can therefore be a powerful tool for social mobility, though it must be accompanied by protections that prevent rising costs from pushing long-standing residents out of their homes. Ultimately, infrastructure decisions reveal whose interests are considered important, and fair planning requires asking who benefits, who pays, and who is left out of the picture.",
   questions: [{q: "What can infrastructure placement determine?", options: ["Only the weather", "Which neighbourhoods flourish and who has access to resources", "The color of buildings", "The price of food"], answer: 1}, {q: "What have historians documented about such decisions?", options: ["That they reflect the priorities of powerful interest groups", "That they are always fair", "That communities decide them", "That they are random"], answer: 0}, {q: "What do contemporary planners emphasize?", options: ["Technical efficiency alone", "Participatory processes", "Secret decision-making", "Ignoring communities"], answer: 1}]},
  {id: 69, level: 3, title: "The Gig Platform's Dilemma",
   text: "Digital labor platforms have reconfigured the relationship between firms and workers. By classifying participants as independent contractors, companies can offer flexibility while avoiding many obligations traditionally associated with employment. Courts and regulators across several jurisdictions have challenged this arrangement, arguing that algorithmic control over pricing, performance ratings, and access to work resembles managerial supervision. The resulting litigation exposes a tension between the entrepreneurial freedom that platforms celebrate and the dependency that many workers actually experience. The debate over intervention in digital platforms also touches on the question of who should bear responsibility for harm. Some argue that companies should be held liable for content they amplify through recommendation systems, while others warn that such liability could encourage excessive removal of legitimate speech. Lawmakers have explored several approaches, including transparency reports, independent audits of algorithms, and user controls that allow people to reduce exposure to certain types of material. Each approach involves trade-offs between safety, privacy, and freedom of expression. Ultimately, platform workers and the companies that employ them must find a settlement that recognizes both the value of flexibility and the real vulnerability of those who depend on it.",
   questions: [{q: "How have platforms classified many participants?", options: ["As employees", "As independent contractors", "As government staff", "As volunteers"], answer: 1}, {q: "Why have courts challenged this arrangement?", options: ["Because algorithmic control resembles managerial supervision", "Because platforms are illegal", "Because workers are too rich", "Because contracts are written in Latin"], answer: 0}, {q: "What tension does the litigation expose?", options: ["Between freedom platforms celebrate and dependency workers experience", "Between two languages", "Between prices and taxes", "Between cities and villages"], answer: 0}]},
  {id: 70, level: 3, title: "Biodiversity and Medicine",
   text: "Natural ecosystems remain a vast and largely unexplored pharmacy. A substantial proportion of modern medicines derive from compounds first identified in plants, fungi, or marine organisms. Yet many species are disappearing before scientists have even catalogued them, potentially eliminating molecules of therapeutic value. Conservation, in this light, is not merely an aesthetic or moral concern but a pragmatic investment in future health. Economists have attempted to quantify the value of biodiversity, though such estimates inevitably rely on assumptions that are difficult to verify. Biodiversity science also depends on long-term monitoring. Scientists who count species in the same locations year after year can detect subtle changes that would otherwise go unnoticed, such as shifts in flowering times, the arrival of invasive plants, or the gradual decline of a fish population. Such data are expensive to collect and require patient, sustained funding, which is often difficult to secure. Citizen science projects have helped to fill this gap, enlisting volunteers to record birds, insects, and plants in their own neighbourhoods and contributing observations that researchers could never gather alone. Ultimately, biodiversity is a form of wealth that is easy to overlook, yet it supports medicine, food, and the stability of the living systems on which every human community depends.",
   questions: [{q: "Where do many modern medicines originate?", options: ["Only from laboratories", "From compounds found in plants, fungi, and marine organisms", "From minerals only", "From synthetic materials only"], answer: 1}, {q: "Why is conservation described as pragmatic?", options: ["Because it is cheap", "Because it is an investment in future health", "Because it makes landscapes beautiful", "Because it avoids all research"], answer: 1}, {q: "What limitation do economists' valuations face?", options: ["They are always precise", "They rely on assumptions that are difficult to verify", "They are never attempted", "They ignore species entirely"], answer: 1}]},
  {id: 71, level: 3, title: "The Ethics of Forgetting",
   text: "The digital age has made forgetting increasingly difficult. Information once lost to time now persists indefinitely in archives, social networks, and search indices. Some legal systems have responded by recognizing a right to erasure, allowing individuals to request the removal of certain personal data. Critics contend that such rights may conflict with public interest in historical records and freedom of expression. The debate exposes a deeper question about whether a society should aspire to perfect recollection, or whether a measure of oblivion serves human flourishing. Forgetting can also serve as a form of mercy. Individuals who carry painful memories may find that the constant recall of trauma prevents them from moving forward. Therapists sometimes help clients reframe difficult experiences rather than erase them, creating a narrative in which the past is acknowledged but no longer dominates present decisions. Societies, too, sometimes choose to set aside grievances in order to rebuild trust, a process that requires honest remembrance alongside a deliberate decision not to let every injury define the future. Ultimately, the ethics of forgetting ask us to balance the right to start again with the public interest in an honest record, a balance that will continue to shape law and daily life.",
   questions: [{q: "Why has forgetting become more difficult?", options: ["Because people have better memories", "Because information persists indefinitely in digital archives", "Because libraries are larger", "Because laws require it"], answer: 1}, {q: "What have some legal systems recognized?", options: ["A right to erasure", "A right to unlimited surveillance", "A duty to publish everything", "A ban on the internet"], answer: 0}, {q: "What deeper question does the debate expose?", options: ["Whether perfect recollection is desirable or some oblivion serves flourishing", "Whether computers are useful", "Whether letters are expensive", "Whether books should be burned"], answer: 0}]},
  {id: 72, level: 3, title: "Metaphor and Thought",
   text: "Metaphor is frequently dismissed as a decorative flourish, yet cognitive linguists argue that it structures much of ordinary thinking. Expressions such as \"time is money\" or \"argument is war\" do not merely adorn speech; they shape how people reason about abstract domains. The metaphors we habitually employ channel attention toward some features of a situation and away from others. Recognizing these hidden frames allows speakers to examine their assumptions and, if necessary, to adopt alternative conceptualisations. Metaphors also carry cultural assumptions that vary between societies. A metaphor that feels natural in one language may seem strange or even offensive in another, which is one reason why translators must pay attention to figurative language with particular care. Scholars who study conceptual metaphor have also argued that some metaphors appear across many cultures, suggesting shared patterns of embodied experience. Others are specific to local histories, landscapes, or technologies, showing how thought is shaped by the environment in which people live and work. Ultimately, the study of metaphor reminds us that language is not a neutral window onto reality, but a lens that shapes what we notice, what we ignore, and how we decide what matters.",
   questions: [{q: "How is metaphor frequently dismissed?", options: ["As a central tool of thought", "As a decorative flourish", "As a scientific method", "As a legal term"], answer: 1}, {q: "What do cognitive linguists argue?", options: ["That metaphor structures much of ordinary thinking", "That metaphor is useless", "That metaphor is only in poetry", "That metaphor is a mathematical rule"], answer: 0}, {q: "What do hidden frames allow speakers to do?", options: ["Ignore all assumptions", "Examine their assumptions and adopt alternatives", "Avoid thinking entirely", "Speak more loudly"], answer: 1}]},
  {id: 73, level: 3, title: "The Persistence of Myths",
   text: "Historical myths possess a remarkable resilience, surviving decades of scholarly correction. Their appeal often lies in narrative simplicity: a single heroic figure or a clear moral lesson is more memorable than the messy interplay of structural forces. Myths also serve identity functions, offering communities a coherent story of origin and purpose. Consequently, debunking a myth requires more than presenting contrary evidence; it demands an alternative narrative that satisfies the same psychological and social needs. Authenticity is also contested in the way communities present their own histories. Local festivals, museums, and guided tours often select particular stories to emphasize, shaping how visitors understand a place. Residents may disagree about which version is most faithful to their experience, especially when the past includes painful episodes that some prefer to downplay. Historians argue that the healthiest approach invites multiple voices into the narrative, allowing the community to acknowledge conflict and change rather than presenting a single, idealised image. Ultimately, the persistence of myths shows that stories are powerful because they answer real needs, and that changing a shared narrative requires addressing those needs with empathy and care.",
   questions: [{q: "Why are historical myths resilient?", options: ["Because scholars ignore them", "Because their narrative simplicity is memorable", "Because they are always true", "Because they are illegal to discuss"], answer: 1}, {q: "What functions do myths serve for communities?", options: ["Economic functions only", "Identity functions, offering a coherent origin story", "Legal functions", "Military functions"], answer: 1}, {q: "What does debunking a myth require, according to the text?", options: ["Only presenting contrary evidence", "An alternative narrative meeting the same needs", "Silencing communities", "Forgetting history"], answer: 1}]},
  {id: 74, level: 3, title: "Water Scarcity and Agriculture",
   text: "Agriculture consumes roughly seventy percent of the world's freshwater withdrawals, a figure that renders irrigation policy central to any strategy for water security. Inefficient systems, such as flood irrigation, can waste substantial quantities through evaporation and runoff. Drip technology, by contrast, delivers water directly to roots with markedly greater precision. Yet efficiency gains may paradoxically increase total consumption if farmers expand cultivated areas with the water saved. Sustainable management therefore requires attention not only to technical improvements but also to the institutional incentives that govern how water is used. Farmers themselves often have valuable knowledge about water management, built up through generations of observing rainfall, soil moisture, and crop responses. When policymakers involve farmers in designing irrigation schemes, the resulting measures tend to be more practical and more widely accepted. Some regions have established water user associations that share responsibility for maintaining canals and allocating supplies during dry seasons. Such local institutions can be more flexible than national regulations, although they require clear rules and transparent accounting to avoid disputes between neighbouring communities. Ultimately, the water question is as much about governance and fairness as it is about engineering, because the most efficient system can still fail if its rewards are poorly distributed.",
   questions: [{q: "What share of freshwater does agriculture consume?", options: ["About ten percent", "Roughly seventy percent", "About half", "Almost none"], answer: 1}, {q: "Why can efficiency gains paradoxically increase consumption?", options: ["Because drip systems leak", "Because farmers may expand cultivated areas with the water saved", "Because water becomes salty", "Because evaporation stops"], answer: 1}, {q: "What does sustainable management require beyond technical improvements?", options: ["Ignoring institutions", "Attention to institutional incentives", "Stopping all farming", "Importing all food"], answer: 1}]},
  {id: 75, level: 3, title: "The Language of Diplomacy",
   text: "Diplomatic communication is notoriously circumspect, employing qualifications and conditional phrasing to preserve flexibility while signalling intent. A phrase such as \"the parties took note of\" can convey acknowledgement without endorsement, while \"regrets\" may express sympathy without admitting fault. Such formulations are not evasive by accident; they reflect a deliberate calibration of commitment. Experienced observers therefore read diplomatic statements not only for their literal content but also for what they omit, emphasize, or soften. Diplomatic language is also shaped by the audiences it must satisfy. A statement may be read simultaneously by domestic critics, foreign governments, allied partners, and the general public, each interpreting it through their own priorities. For this reason, drafters often build in carefully balanced sentences that offer reassurance to one audience without alienating another. The result can be frustrating for observers who want clear answers, but it reflects the reality that diplomacy works by keeping channels open even when the parties disagree deeply. Ultimately, the study of diplomatic language reminds us that words in international affairs are chosen with great care, because their meaning can shift dramatically depending on who is listening and why.",
   questions: [{q: "How is diplomatic communication described?", options: ["Blunt and direct", "Notoriously circumspect", "Purely technical", "Always humorous"], answer: 1}, {q: "What can the phrase \"the parties took note of\" convey?", options: ["Full endorsement", "Acknowledgement without endorsement", "Immediate war", "Personal friendship"], answer: 1}, {q: "How do experienced observers read diplomatic statements?", options: ["Only for literal content", "For what they omit, emphasize, or soften", "Without any attention", "Only in translation"], answer: 1}]}
];
